// The live PARALLAX voice is generated by Qwen3-TTS using the local V6
// VoiceDesign audition as its speaker reference.
export const PARALLAX_VOICE = Object.freeze({
  id: "parallax-v6",
  name: "PARALLAX V6 (Qwen3-TTS)",
});

export function cleanSpeechText(value = "") {
  return String(value)
    .replace(/\x60{3}[\s\S]*?\x60{3}/g, "Code block omitted.")
    .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
    .replace(/https?:\/\/\S+/g, "")
    .replace(/^\s{0,3}#{1,6}\s+/gm, "")
    .replace(/\*\*(.*?)\*\*/g, "$1")
    .replace(/\*(.*?)\*/g, "$1")
    .replace(/__(.*?)__/g, "$1")
    .replace(/_(.*?)_/g, "$1")
    .replace(/\x60([^\x60]+)\x60/g, "$1")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

export async function synthesizeSpeech(text, { signal } = {}) {
  const spokenText = cleanSpeechText(text);
  if (!spokenText) throw new Error("There is no text to speak.");

  const response = await fetch("/api/tts/v1/audio/speech", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    signal,
    body: JSON.stringify({
      model: "qwen3-tts",
      input: spokenText,
      voice: PARALLAX_VOICE.id,
      response_format: "wav",
    }),
  });

  if (!response.ok) {
    const error = await response.json().catch(() => ({}));
    throw new Error(error.error || "Local voice service returned " + response.status);
  }

  return URL.createObjectURL(await response.blob());
}
